use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum TokenKind {
    // Original core keywords
    Vector,
    Wallet,
    Bind,
    Certify,
    Transfer,
    Drain,
    Project,
    Reconstruct,
    Query,
    Record,
    Contract,
    Action,
    With,
    To,
    Amount,
    By,
    Into,
    From,
    Policy,
    Ctx,
    Space,
    Op,
    Risk,
    ThresholdVersion,
    Outcome,
    Gain,
    Loss,
    Partial,
    Release,
    Staged,
    As,

    // Network & Protocol keywords
    Import,
    Network,
    Connect,
    Target,
    Participant,
    Join,
    Scope,
    Region,
    Ghost,
    Token,
    Create,
    In,
    Authorize,
    Key,
    Role,
    Receive,
    Execute,
    Loan,
    Verify,
    Proof,
    History,
    Blake3,
    Sha256,
    Public,
    Private,
    Bool(bool),

    // Punctuation
    Eq,
    Colon,
    Semi,
    Comma,
    Dot,
    LParen,
    RParen,
    LBrace,
    RBrace,
    LBracket,
    RBracket,

    // Literals & Identifiers
    Integer(u128),
    String(String),
    Ident(String),
    Eof,
}

impl TokenKind {
    /// Returns the identifier spelling for keywords that may appear as field/property names
    /// inside `ctx(...)` or `{ field = value; }` blocks.
    pub fn as_ident_str(&self) -> Option<&str> {
        match self {
            TokenKind::Ident(s) => Some(s.as_str()),
            TokenKind::Vector => Some("vector"),
            TokenKind::Wallet => Some("wallet"),
            TokenKind::Bind => Some("bind"),
            TokenKind::Certify => Some("certify"),
            TokenKind::Transfer => Some("transfer"),
            TokenKind::Drain => Some("drain"),
            TokenKind::Project => Some("project"),
            TokenKind::Reconstruct => Some("reconstruct"),
            TokenKind::Query => Some("query"),
            TokenKind::Record => Some("record"),
            TokenKind::Contract => Some("contract"),
            TokenKind::Action => Some("action"),
            TokenKind::With => Some("with"),
            TokenKind::To => Some("to"),
            TokenKind::Amount => Some("amount"),
            TokenKind::By => Some("by"),
            TokenKind::Into => Some("into"),
            TokenKind::From => Some("from"),
            TokenKind::Policy => Some("policy"),
            TokenKind::Ctx => Some("ctx"),
            TokenKind::Space => Some("space"),
            TokenKind::Op => Some("op"),
            TokenKind::Risk => Some("risk"),
            TokenKind::ThresholdVersion => Some("threshold_version"),
            TokenKind::Outcome => Some("outcome"),
            TokenKind::Gain => Some("gain"),
            TokenKind::Loss => Some("loss"),
            TokenKind::Partial => Some("partial"),
            TokenKind::Release => Some("release"),
            TokenKind::Staged => Some("staged"),
            TokenKind::As => Some("as"),
            TokenKind::Import => Some("import"),
            TokenKind::Network => Some("network"),
            TokenKind::Connect => Some("connect"),
            TokenKind::Target => Some("target"),
            TokenKind::Participant => Some("participant"),
            TokenKind::Join => Some("join"),
            TokenKind::Scope => Some("scope"),
            TokenKind::Region => Some("region"),
            TokenKind::Ghost => Some("ghost"),
            TokenKind::Token => Some("token"),
            TokenKind::Create => Some("create"),
            TokenKind::In => Some("in"),
            TokenKind::Authorize => Some("authorize"),
            TokenKind::Key => Some("key"),
            TokenKind::Role => Some("role"),
            TokenKind::Receive => Some("receive"),
            TokenKind::Execute => Some("execute"),
            TokenKind::Loan => Some("loan"),
            TokenKind::Verify => Some("verify"),
            TokenKind::Proof => Some("proof"),
            TokenKind::History => Some("history"),
            TokenKind::Blake3 => Some("blake3"),
            TokenKind::Sha256 => Some("sha256"),
            TokenKind::Public => Some("public"),
            TokenKind::Private => Some("private"),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Token {
    pub kind: TokenKind,
    pub start: usize,
    pub end: usize,
    pub line: usize,
    pub col: usize,
}

impl Token {
    pub fn new(kind: TokenKind, start: usize, end: usize, line: usize, col: usize) -> Self {
        Self {
            kind,
            start,
            end,
            line,
            col,
        }
    }
}
